import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const root = new THREE.Group();

  // Apply scene transformation
  root.position.set(...config.scenePosition);
  root.rotation.set(...config.sceneRotation);
  root.scale.set(...config.sceneScale);

  // Load the GLB mesh via cached loader
  const gltf = ctx.glbLoader(config.assets.meshUrl);
  const meshClone = gltf.scene.clone();
  root.add(meshClone);

  // Store original transform values for animation reversals
  const originalY = config.scenePosition[1];
  const originalScaleX = config.sceneScale[0];
  const originalScaleY = config.sceneScale[1];
  const originalScaleZ = config.sceneScale[2];

  // Initialize interaction handlers object
  root.userData.handlers = {};

  // Hover handler: apply rise-in animation (0.15 scene units up)
  root.userData.handlers.hover = function() {
    gsap.to(root.position, {
      y: originalY + 0.15,
      duration: 0.7,
      ease: 'power3.out'
    });
  };

  // Unhover handler: return to original position
  root.userData.handlers.unhover = function() {
    gsap.to(root.position, {
      y: originalY,
      duration: 0.7,
      ease: 'power3.out'
    });
  };

  // Click handler: press-down effect and navigation event
  root.userData.handlers.click = function() {
    // Press down: scale to 0.97 over 120ms with back.out easing
    const timeline = gsap.timeline();
    timeline.to(root.scale, {
      x: originalScaleX * 0.97,
      y: originalScaleY * 0.97,
      z: originalScaleZ * 0.97,
      duration: 0.12,
      ease: 'back.out'
    }, 0);
    // Restore scale
    timeline.to(root.scale, {
      x: originalScaleX,
      y: originalScaleY,
      z: originalScaleZ,
      duration: 0.12,
      ease: 'back.out'
    });

    // Emit navigation event
    root.dispatchEvent(new Event('hub-home.select'));
  };

  // Apply all cinematic primitives from config
  if (config.cinematicPrimitives && Array.isArray(config.cinematicPrimitives)) {
    config.cinematicPrimitives.forEach((primitive) => {
      if (ctx.primitives && typeof ctx.primitives[primitive.name] === 'function') {
        ctx.primitives[primitive.name](root, primitive.params);
      }
    });
  }

  // Cleanup function: dispose resources and kill animations
  root.userData.cleanup = function() {
    // Kill all GSAP tweens on position and scale
    gsap.killTweensOf(root.position);
    gsap.killTweensOf(root.scale);

    // Recursively dispose geometries and materials from the cloned mesh
    meshClone.traverse((child) => {
      if (child.geometry) {
        child.geometry.dispose();
      }
      if (child.material) {
        if (Array.isArray(child.material)) {
          child.material.forEach((mat) => {
            mat.dispose();
          });
        } else {
          child.material.dispose();
        }
      }
    });
  };

  return root;
}
